<template>
  <section class="documents">
    <h2>Заселение</h2>

    <button
      @click="fetchHotelData"
      :disabled="isLoading || auth.isLoading"
    >
      {{ isLoading ? 'Обработка...' : 'Получить данные по размещению' }}
    </button>

    <!-- Результат -->
    <div v-if="hotelData && Object.keys(hotelData).length > 0" class="hotel-info">
      <h3>Данные по номерам в отеле:</h3>

      <div v-for="(rooms, roomType) in hotelData" :key="roomType">
        <h4>{{ roomType }} ({{ rooms.length }} номеров)</h4>

        <div
          v-for="(room, roomIndex) in rooms"
          :key="roomIndex"
          class="room-block"
        >
          <h5>Номер {{ roomIndex + 1 }}</h5>

          <div
            v-for="(guest, guestIndex) in room"
            :key="guestIndex"
          >
            <strong>Гость {{ guestIndex + 1 }}:</strong>
            <div class="guest-form">
              <input
                v-model="hotelData[roomType][roomIndex][guestIndex].fio"
                placeholder="ФИО"
              />
              <input
                v-model="hotelData[roomType][roomIndex][guestIndex].passport"
                placeholder="Паспортные данные"
              />
              <input
                v-model="hotelData[roomType][roomIndex][guestIndex].phone"
                placeholder="Номер телефона"
              />
            </div>
          </div>

          <button
            @click="updateSingleRoom(roomType, roomIndex)"
            :disabled="updatingRooms[`${roomType}-${roomIndex}`]"
            class="save-room-btn"
          >
            {{ updatingRooms[`${roomType}-${roomIndex}`] ? 'Сохранение...' : 'Сохранить номер' }}
          </button>

          <span
            v-if="saveMessages[`${roomType}-${roomIndex}`]"
            class="mini-status"
            :class="{ 'error-message': saveMessages[`${roomType}-${roomIndex}`].startsWith('Ошибка') }"
          >
            {{ saveMessages[`${roomType}-${roomIndex}`] }}
          </span>
        </div>
      </div>

      <p v-if="docUrl">
        Документ:
        <a :href="docUrl" target="_blank" rel="noopener noreferrer">
          Открыть Google Документ
        </a>
      </p>

      <p v-if="docMessage" class="status">{{ docMessage }}</p>
    </div>

    <p v-else-if="hotelData && Object.keys(hotelData).length === 0" class="status">
      Документ существует, но в нём нет данных по номерам.
    </p>

    <p v-if="errorMessage" class="error">{{ errorMessage }}</p>
  </section>
</template>

<script>
import { useAuthStore } from '@/stores/auth'

export default {
  name: 'HotelCheckIn',

  setup() {
    const auth = useAuthStore()
    return { auth }
  },

  data() {
    return {
      hotelData: null,
      docUrl: null,
      docMessage: null,
      errorMessage: null,
      isLoading: false,

      // Для индикации загрузки и сообщений по каждой комнате
      updatingRooms: {},
      saveMessages: {},
    }
  },

  methods: {
    async fetchHotelData() {
      this.isLoading = true
      this.errorMessage = null
      this.hotelData = null
      this.docUrl = null
      this.docMessage = null

      try {
        const response = await this.auth.createGoogleDoc({ action: 'create' })

        if (response?.status === 'success') {
          this.hotelData = response.data || {}
          this.docUrl = response.url || null
          this.docMessage = response.message || 'Данные получены'

          if (response.message?.includes('существующего')) {
            this.docMessage = 'Данные взяты из уже существующего документа'
          } else if (response.message?.includes('Новый')) {
            this.docMessage = 'Создан новый документ с данными'
          }
        } else {
          this.errorMessage = response?.message || 'Не удалось получить данные'
        }
      } catch (err) {
        console.error('Ошибка при получении данных:', err)
        this.errorMessage = 'Произошла ошибка при обращении к серверу'
      } finally {
        this.isLoading = false
      }
    },

    async updateSingleRoom(roomType, roomIndex) {
      const key = `${roomType}-${roomIndex}`

      this.updatingRooms[key] = true
      this.saveMessages[key] = null
      this.errorMessage = null

      try {
        const roomData = this.hotelData[roomType]?.[roomIndex]

        if (!roomData) {
          throw new Error('Данные комнаты не найдены')
        }

        const payload = {
          roomType,
          roomIndex,
          guests: roomData  // массив гостей этой комнаты
        }

        const response = await this.auth.createGoogleDoc({
          action: 'update_room',
          extraData: payload
        })

        if (response?.status === 'success') {
          this.saveMessages[key] = 'Сохранено ✓'
          setTimeout(() => {
            delete this.saveMessages[key]
          }, 4000)
        } else {
          this.saveMessages[key] = 'Ошибка: ' + (response?.message || 'неизвестная ошибка')
        }
      } catch (err) {
        console.error('Ошибка при сохранении номера:', err)
        this.saveMessages[key] = 'Ошибка соединения'
        this.errorMessage = 'Не удалось сохранить изменения'
      } finally {
        this.updatingRooms[key] = false
      }
    }
  }
}
</script>

